	b := []float64{1, 5}
	r := NewRecorder(b)
	b[0] = 100
	r.Record("x", ms(1))
	if got := r.Quantile("x", 100); got != 1 {
		t.Errorf("le Recorder partage la slice de bornes de l'appelant (Quantile = %v, attendu 1)", got)
	}
