				}
			}
			delete(d, "name")
			d["first_name"], d["last_name"] = first, last
			return d, nil
		},
		func(d Doc) (Doc, error) {
			if city, ok := d["city"]; ok {
				d["address"] = map[string]any{"city": city}
				delete(d, "city")
			}
