package lab

import (
	"errors"
)

// ---------- Jalon 1 : vecteurs de version et compteurs convergents ----------

// VV est un vecteur de version : un compteur par réplica.
type VV map[string]uint64

// Order est le résultat de la comparaison de deux vecteurs.
type Order int

