	if got := OpenLoop([]float64{1, 2}, []float64{1}); got != nil {
		t.Errorf("longueurs différentes : %v, attendu nil", got)
	}
}

func TestClosedLoopHidesTheQueue(t *testing.T) {
	got := ClosedLoop(service)
	if !reflect.DeepEqual(got, service) {
