package lab

// Report décrit ce que CheckFormat a trouvé dans une chaîne de format.
type Report struct {
	Verbs    []string // verbes complets, dans l'ordre : "%d", "%-5s", "%.2f"
	Unknown  []string // verbes que fmt ne connaît pas : "%z"
