		{0, 2, []int64{0, 0}},
		{10, 1, []int64{10}},
		{7, 5, []int64{2, 2, 1, 1, 1}},
	}
	for _, c := range cases {
		if got := SplitBill(c.total, c.n); !slices.Equal(got, c.want) {
