func TestSessionClosesWhatWasOpenedOnError(t *testing.T) {
	got, err := Session([]string{"a", "b", "", "d"})
	want := []string{"open a", "open b", "close b", "close a"}
	if !errors.Is(err, ErrEmptyName) || !slices.Equal(got, want) {
