func TestNilListsDoNotPanic(t *testing.T) {
	var l *List
	Push(l, 1)
	Append(l, 1)
	Reverse(l)
	InsertSorted(l, 1)
	if v, ok := Pop(l); ok || v != 0 {
		t.Errorf("Pop(nil) = (%d, %v)", v, ok)
