	for i := 0; i < 500; i++ {
		switch i % 4 {
		case 0:
			Push(l, i)
			want = slices.Insert(want, 0, i)
		case 1:
			Append(l, i)
			want = append(want, i)
		case 2:
			if i%3 == 0 && len(want) > 0 {
				Remove(l, want[len(want)/2])
				want = slices.Delete(want, len(want)/2, len(want)/2+1)
			}
		case 3:
			if v, ok := Pop(l); ok {
				if v != want[0] {
					t.Fatalf("Pop = %d, attendu %d", v, want[0])
				}
				want = want[1:]
			}
		}
	}
	check(t, "après 500 opérations mélangées", l, want)
}

