	for _, in := range []string{"", "   ", "\t\n"} {
		if got, err := ParseOptionalInt(in); got != nil || err != nil {
			t.Errorf("ParseOptionalInt(%q) = (%v, %v), attendu (nil, nil) : une valeur absente n'est pas une erreur", in, got, err)
